package nl.voetbalhub.app;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;
/** Official NOS catalogue. External playback avoids WebView restrictions and tracking before a click. */
public final class VideoShelf40 extends FrameLayout {
 private final Activity a;private final LinearLayout list;private boolean attached,loading;private JSONObject snapshot;
 private static final java.util.concurrent.ExecutorService IO=java.util.concurrent.Executors.newFixedThreadPool(1);
 private int dp(float n){return PremiumDesign40.dp(a,n);}
 public VideoShelf40(Activity a){super(a);this.a=a;setBackgroundColor(PremiumDesign40.INK);ScrollView scroll=new ScrollView(a);list=new LinearLayout(a);list.setOrientation(1);list.setPadding(dp(16),dp(14),dp(16),dp(28));scroll.addView(list);addView(scroll,new LayoutParams(-1,-1));try{snapshot=new JSONObject(a.getSharedPreferences("nos42",0).getString("snapshot","{}"));}catch(Exception ignored){}render(snapshot);}
 private void load(){if(loading||!attached)return;loading=true;render(snapshot);IO.execute(()->{JSONObject data=null;try{JSONObject r=new JSONObject(DeadlineHttp.get("https://raw.githubusercontent.com/sanderbrink-spec/Voetbalhub/work/veldio-42/videos/nos42.json",12000,500000));if(r.optInt("schemaVersion")==42)data=r;}catch(Exception ignored){}final JSONObject result=data;a.runOnUiThread(()->{loading=false;if(!attached)return;if(result!=null){snapshot=result;a.getSharedPreferences("nos42",0).edit().putString("snapshot",result.toString()).apply();}render(snapshot);});});}
 private void open(String url){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(a,"Geen YouTube-app of browser beschikbaar",Toast.LENGTH_SHORT).show();}}
 private void render(JSONObject data){list.removeAllViews();list.addView(PremiumDesign40.text(a,"SAMENVATTINGEN",25,PremiumDesign40.WHITE,true));boolean fresh=false;try{fresh=data!=null&&java.time.Instant.parse(data.getString("expiresAt")).toEpochMilli()>System.currentTimeMillis();}catch(Exception ignored){}
 int round=fresh?data.optInt("round"):0;list.addView(PremiumDesign40.text(a,round>0?"Eredivisie | Speelronde "+round+" · "+data.optString("season"):"Eredivisie | NOS Sport",15,PremiumDesign40.GREEN,true));
 list.addView(PremiumDesign40.text(a,"Afspelen in de officiële YouTube-app of browser",12,PremiumDesign40.MUTED,false));int count=0;JSONArray rows=fresh?data.optJSONArray("videos"):null;
 if(rows!=null)for(int i=0;i<rows.length()&&count<9;i++){JSONObject v=rows.optJSONObject(i);if(v==null||!v.optString("id").matches("[A-Za-z0-9_-]{11}")||!"NOS Sport".equals(v.optString("channel"))||v.optInt("round")!=round||!v.optString("season").equals(data.optString("season")))continue;final String id=v.optString("id");LinearLayout card=new LinearLayout(a);card.setOrientation(1);card.setPadding(dp(14),dp(14),dp(14),dp(14));PremiumDesign40.card(card,PremiumDesign40.EDGE);card.addView(PremiumDesign40.text(a,"▶  "+v.optString("match",v.optString("title")),17,PremiumDesign40.WHITE,true));card.addView(PremiumDesign40.text(a,"NOS Sport · YouTube · "+v.optString("publishedAt").replace('T',' ').replace('Z',' '),11,PremiumDesign40.MUTED,false));card.setOnClickListener(x->open("https://www.youtube.com/watch?v="+id));PremiumDesign40.touch(card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(12);list.addView(card,lp);count++;}
 TextView state=PremiumDesign40.text(a,loading?"Samenvattingen bijwerken…":count==0?"Nog geen gecontroleerd speelrondeoverzicht beschikbaar. Bekijk de beschikbare samenvattingen bij NOS Sport op YouTube.":count<9?"Nog niet alle samenvattingen zijn gepubliceerd.":"Alle negen samenvattingen beschikbaar.",14,PremiumDesign40.MUTED,false);state.setPadding(0,dp(20),0,dp(12));list.addView(state);
 Button source=new Button(a);source.setText("NOS Sport op YouTube openen ↗");source.setOnClickListener(x->open("https://www.youtube.com/@nossport"));PremiumDesign40.polish(source);list.addView(source);Button retry=new Button(a);retry.setText(loading?"Bezig met laden…":"Vernieuwen");retry.setEnabled(!loading);retry.setOnClickListener(x->load());PremiumDesign40.polish(retry);list.addView(retry);
 }
 public boolean closeVideo(){return false;}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;load();}
 @Override protected void onDetachedFromWindow(){attached=false;super.onDetachedFromWindow();}
}
